impl FailedNodeExceptionWire {
    pub fn resource_not_found(node_id: String, reason: String) -> Self {
        Self {
            message: Some(format!("Failed node [{node_id}]")),
            node_id,
            cause: Some(TransportError {
                class_name: "org.opensearch.ResourceNotFoundException".to_string(),
                message: Some(reason),
                cause: None,
            }),
        }
    }

    pub fn illegal_argument(node_id: String, reason: String) -> Self {
        Self {
            message: Some(format!("Failed node [{node_id}]")),
            node_id,
            cause: Some(TransportError {
                class_name: "java.lang.IllegalArgumentException".to_string(),
                message: Some(reason),
                cause: None,
            }),
        }
    }

    pub fn write(&self, output: &mut StreamOutput) -> Result<(), TransportActionWireError> {
        output.write_optional_string(self.message.as_deref());
        write_supported_exception(output, self.cause.as_ref())?;
        write_empty_stack_trace(output);
        write_empty_string_list_map(output);
        write_empty_string_list_map(output);
        output.write_optional_string(Some(&self.node_id));
        Ok(())
    }

    pub fn read(input: &mut StreamInput) -> Result<Self, TransportActionWireError> {
        let message = input.read_optional_string()?;
        let cause = read_exception(input)?;
        skip_stack_trace(input)?;
        skip_string_list_map(input)?;
        skip_string_list_map(input)?;
        let node_id =
            input
                .read_optional_string()?
                .ok_or(TransportActionWireError::MissingRequiredField {
                    field: "failed node id",
                })?;
        Ok(Self {
            node_id,
            message,
            cause,
        })
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ListTaskInfoWire {
    pub node_id: String,
    pub task_id: i64,
    pub task_type: String,
    pub action: String,
    pub description: Option<String>,
    pub start_time_millis: i64,
    pub running_time_nanos: i64,
    pub cancellable: bool,
    pub cancelled: bool,
    pub parent_task_node: String,
    pub parent_task_id: Option<i64>,
    pub headers: BTreeMap<String, String>,
    pub cancellation_start_time_millis: Option<i64>,
}

impl ListTaskInfoWire {
    pub fn write(&self, output: &mut StreamOutput) {
        write_task_id_fields(output, &self.node_id, Some(self.task_id));
        output.write_string(&self.task_type);
        output.write_string(&self.action);
        output.write_optional_string(self.description.as_deref());
        write_optional_named_writeable_marker(output, None);
        output.write_i64(self.start_time_millis);
        output.write_i64(self.running_time_nanos);
        output.write_bool(self.cancellable);
        output.write_bool(self.cancelled);
        write_task_id_fields(output, &self.parent_task_node, self.parent_task_id);
        output.write_string_map(&self.headers);
        output.write_bool(false);
        write_optional_i64(output, self.cancellation_start_time_millis);
    }

    pub fn read(input: &mut StreamInput) -> Result<Self, TransportActionWireError> {
        let task_id = TaskIdWire::read(input)?;
        let Some(id) = task_id.id else {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "list tasks task info id",
                reason: "task info entries require concrete OpenSearch task ids",
            });
        };
        let task_type = input.read_string()?;
        let action = input.read_string()?;
        let description = input.read_optional_string()?;
        if read_optional_named_writeable_marker(input)?.is_some() {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "list tasks task status",
                reason: "detailed task status named writeables are not decoded by this adapter yet",
            });
        }
        let start_time_millis = input.read_i64()?;
        let running_time_nanos = input.read_i64()?;
        let cancellable = input.read_bool()?;
        let cancelled = input.read_bool()?;
        if !cancellable && cancelled {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "list tasks cancellation state",
                reason: "OpenSearch task info cannot be cancelled unless it is cancellable",
            });
        }
        let parent_task = TaskIdWire::read(input)?;
        let headers = input.read_string_map()?;
        if input.read_bool()? {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "list tasks resource stats",
                reason: "task resource stats are not decoded by this adapter yet",
            });
        }
        let cancellation_start_time_millis = read_optional_i64(input)?;
        Ok(Self {
            node_id: task_id.node_id,
            task_id: id,
            task_type,
            action,
            description,
            start_time_millis,
            running_time_nanos,
            cancellable,
            cancelled,
            parent_task_node: parent_task.node_id,
            parent_task_id: parent_task.id,
            headers,
            cancellation_start_time_millis,
        })
    }
}

impl ListTasksResponseWire {
    pub fn empty() -> Self {
        Self {
            task_failure_count: 0,
            node_failures: Vec::new(),
            tasks: Vec::new(),
        }
    }

    pub fn write(&self, output: &mut StreamOutput) -> Result<(), TransportActionWireError> {
        if self.task_failure_count != 0 {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "list tasks task failures",
                reason: "task failure exception payloads are not encoded by this adapter yet",
            });
        }
        output.write_vint(0);
        output.write_vint(self.node_failures.len() as i32);
        for failure in &self.node_failures {
            failure.write(output)?;
        }
        output.write_vint(self.tasks.len() as i32);
        for task in &self.tasks {
            task.write(output);
        }
        Ok(())
    }

    pub fn read(bytes: Bytes) -> Result<Self, TransportActionWireError> {
        let mut input = StreamInput::new(bytes);
        let task_failure_count = input.read_vint()?;
        if task_failure_count != 0 {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "list tasks task failures",
                reason: "task failure exception payloads are not decoded by this adapter yet",
            });
        }
        let node_failure_count = read_len(&mut input)?;
        let mut node_failures = Vec::with_capacity(node_failure_count);
        for _ in 0..node_failure_count {
            node_failures.push(FailedNodeExceptionWire::read(&mut input)?);
        }
        let task_count = read_len(&mut input)?;
        let mut tasks = Vec::with_capacity(task_count);
        for _ in 0..task_count {
            tasks.push(ListTaskInfoWire::read(&mut input)?);
        }
        require_no_trailing_bytes(&input)?;
        Ok(Self {
            task_failure_count,
            node_failures,
            tasks,
        })
    }
}

fn write_supported_exception(
    output: &mut StreamOutput,
    error: Option<&TransportError>,
) -> Result<(), TransportActionWireError> {
    let Some(error) = error else {
        output.write_bool(false);
        return Ok(());
    };
    output.write_bool(true);
    match error.class_name.as_str() {
        "org.opensearch.ResourceNotFoundException" => {
            output.write_vint(0);
            output.write_vint(19);
            output.write_optional_string(error.message.as_deref());
            write_supported_exception(output, error.cause.as_deref())?;
            write_empty_stack_trace(output);
            write_empty_string_list_map(output);
            write_empty_string_list_map(output);
        }
        "java.lang.IllegalArgumentException" => {
            output.write_vint(6);
            output.write_optional_string(error.message.as_deref());
            write_supported_exception(output, error.cause.as_deref())?;
            write_empty_stack_trace(output);
        }
        _ => {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "failed node exception cause",
                reason: "only ResourceNotFoundException and IllegalArgumentException causes are encoded by this adapter",
            });
        }
    }
    Ok(())
}

fn write_empty_stack_trace(output: &mut StreamOutput) {
    output.write_vint(0);
    output.write_vint(0);
}

fn write_empty_string_list_map(output: &mut StreamOutput) {
    output.write_vint(0);
}

fn skip_stack_trace(input: &mut StreamInput) -> Result<(), TransportActionWireError> {
    let frame_count = read_len(input)?;
    for _ in 0..frame_count {
        let _declaring_class = input.read_string()?;
        let _file_name = input.read_optional_string()?;
        let _method_name = input.read_string()?;
        let _line_number = input.read_vint()?;
    }
    let suppressed_count = read_len(input)?;
    for _ in 0..suppressed_count {
        let _suppressed = read_exception(input)?;
    }
    Ok(())
}

fn skip_string_list_map(input: &mut StreamInput) -> Result<(), TransportActionWireError> {
    let len = read_len(input)?;
    for _ in 0..len {
        let _key = input.read_string()?;
        let values_len = read_len(input)?;
        for _ in 0..values_len {
            let _value = input.read_string()?;
        }
    }
    Ok(())
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct GetTaskRequestWire {
    pub parent_task_node: String,
    pub parent_task_id: Option<i64>,
    pub task_id: TaskIdWire,
    pub timeout: Option<TimeValueWire>,
    pub wait_for_completion: bool,
}

impl GetTaskRequestWire {
    pub fn new(node_id: String, id: i64) -> Self {
        Self {
            parent_task_node: String::new(),
            parent_task_id: None,
            task_id: TaskIdWire {
                node_id,
                id: Some(id),
            },
            timeout: None,
            wait_for_completion: false,
        }
    }

    pub fn write(&self, output: &mut StreamOutput) {
        write_parent_task_id(output, &self.parent_task_node, self.parent_task_id);
        self.task_id.write(output);
        write_optional_time_value(output, self.timeout.as_ref());
        output.write_bool(self.wait_for_completion);
    }

    pub fn read(bytes: Bytes) -> Result<Self, TransportActionWireError> {
        let mut input = StreamInput::new(bytes);
        let (parent_task_node, parent_task_id) = read_parent_task_id(&mut input)?;
        let request = Self {
            parent_task_node,
            parent_task_id,
            task_id: TaskIdWire::read(&mut input)?,
            timeout: read_optional_time_value(&mut input)?,
            wait_for_completion: input.read_bool()?,
        };
        require_no_trailing_bytes(&input)?;
        Ok(request)
    }

    pub fn validate_supported_execution(&self) -> Result<(), TransportActionWireError> {
        if !self.task_id.is_set() {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get task missing task id",
                reason: "OpenSearch get-task requires an explicit task id",
            });
        }
        if self.timeout.is_some() {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get task timeout",
                reason: "get-task timeout requires runtime task result lifecycle mapping",
            });
        }
        if self.wait_for_completion {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get task wait for completion",
                reason: "wait-for-completion requires runtime task result lifecycle mapping",
            });
        }
        Ok(())
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct GetTaskResponseWire {
    pub task_result_present: bool,
    pub completed: bool,
    pub task: Option<ListTaskInfoWire>,
}

impl GetTaskResponseWire {
    pub fn empty() -> Self {
        Self {
            task_result_present: false,
            completed: false,
            task: None,
        }
    }

    pub fn running(task: ListTaskInfoWire) -> Self {
        Self {
            task_result_present: true,
            completed: false,
            task: Some(task),
        }
    }

    pub fn completed(task: ListTaskInfoWire) -> Self {
        Self {
            task_result_present: true,
            completed: true,
            task: Some(task),
        }
    }

    pub fn write(&self, output: &mut StreamOutput) -> Result<(), TransportActionWireError> {
        output.write_bool(self.task_result_present);
        if !self.task_result_present {
            return Ok(());
        }
        output.write_bool(self.completed);
        let Some(task) = self.task.as_ref() else {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get task result",
                reason: "present task result requires a task info payload",
            });
        };
        task.write(output);
        output.write_bool(false);
        output.write_bool(false);
        Ok(())
    }

    pub fn read(bytes: Bytes) -> Result<Self, TransportActionWireError> {
        let mut input = StreamInput::new(bytes);
        let task_result_present = input.read_bool()?;
        if !task_result_present {
            require_no_trailing_bytes(&input)?;
            return Ok(Self::empty());
        }
        let completed = input.read_bool()?;
        let task = ListTaskInfoWire::read(&mut input)?;
        if input.read_bool()? {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get task error payload",
                reason: "completed task error payloads are not decoded by this adapter yet",
            });
        }
        if input.read_bool()? {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "get task response payload",
                reason: "completed task response payloads are not decoded by this adapter yet",
            });
        }
        require_no_trailing_bytes(&input)?;
        Ok(Self {
            task_result_present,
            completed,
            task: Some(task),
        })
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct CancelTasksRequestWire {
    pub parent_task_node: String,
    pub parent_task_id: Option<i64>,
    pub task_id: TaskIdWire,
    pub parent_task_filter: TaskIdWire,
    pub nodes: Vec<String>,
    pub actions: Vec<String>,
    pub timeout: Option<TimeValueWire>,
    pub reason: String,
    pub wait_for_completion: bool,
}

impl Default for CancelTasksRequestWire {
    fn default() -> Self {
        Self {
            parent_task_node: String::new(),
            parent_task_id: None,
            task_id: TaskIdWire::unset(),
            parent_task_filter: TaskIdWire::unset(),
            nodes: Vec::new(),
            actions: Vec::new(),
            timeout: None,
            reason: "by user request".to_string(),
            wait_for_completion: false,
        }
    }
}

impl CancelTasksRequestWire {
    pub fn write(&self, output: &mut StreamOutput) -> Result<(), TransportActionWireError> {
        self.validate_supported_subset()?;
        write_parent_task_id(output, &self.parent_task_node, self.parent_task_id);
        self.task_id.write(output);
        self.parent_task_filter.write(output);
        output.write_string_array(&self.nodes);
        output.write_string_array(&self.actions);
        write_optional_time_value(output, self.timeout.as_ref());
        output.write_string(&self.reason);
        output.write_bool(self.wait_for_completion);
        Ok(())
    }

    pub fn read(bytes: Bytes) -> Result<Self, TransportActionWireError> {
        let mut input = StreamInput::new(bytes);
        let (parent_task_node, parent_task_id) = read_parent_task_id(&mut input)?;
        let request = Self {
            parent_task_node,
            parent_task_id,
            task_id: TaskIdWire::read(&mut input)?,
            parent_task_filter: TaskIdWire::read(&mut input)?,
            nodes: input.read_string_array()?,
            actions: input.read_string_array()?,
            timeout: read_optional_time_value(&mut input)?,
            reason: input.read_string()?,
            wait_for_completion: input.read_bool()?,
        };
        require_no_trailing_bytes(&input)?;
        request.validate_supported_subset()?;
        Ok(request)
    }

    pub fn validate_supported_subset(&self) -> Result<(), TransportActionWireError> {
        if self.timeout.is_some() {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "cancel tasks timeout",
                reason: "cancel-tasks timeout is not mapped by this adapter yet",
            });
        }
        if self.reason != "by user request" {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "cancel tasks reason",
                reason: "custom cancellation reason is not mapped by this adapter yet",
            });
        }
        if self.wait_for_completion {
            return Err(TransportActionWireError::UnsupportedWireShape {
                shape: "cancel tasks wait for completion",
                reason: "wait-for-completion semantics require tracked runtime task lifecycle",
            });
        }
        Ok(())
    }
}

