    #[test]
    fn opensearch_transport_action_dispatch_marks_priority_targets_explicitly() {
        for spec in OPENSEARCH_PRIORITY_TRANSPORT_ACTIONS {
            let decision = classify_opensearch_transport_action(spec.action_name);
            if spec.action_name == OPENSEARCH_GET_ACTION_NAME
                || spec.action_name == OPENSEARCH_MULTI_GET_ACTION_NAME
                || spec.action_name == OPENSEARCH_BULK_ACTION_NAME
                || spec.action_name == OPENSEARCH_INDEX_ACTION_NAME
                || spec.action_name == OPENSEARCH_UPDATE_ACTION_NAME
                || spec.action_name == OPENSEARCH_DELETE_ACTION_NAME
                || spec.action_name == OPENSEARCH_REFRESH_ACTION_NAME
                || spec.action_name == OPENSEARCH_INDICES_STATS_ACTION_NAME
                || spec.action_name == OPENSEARCH_RECOVERY_ACTION_NAME
            {
                assert_eq!(
                    decision.disposition,
                    OpenSearchTransportActionDisposition::Implemented,
                    "{}",
                    spec.action_name
                );
                continue;
            }
            if spec.action_name == OPENSEARCH_TERM_VECTORS_ACTION_NAME
                || spec.action_name == OPENSEARCH_MULTI_TERM_VECTORS_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_MAPPINGS_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_FIELD_MAPPINGS_ACTION_NAME
                || spec.action_name == OPENSEARCH_PUT_MAPPING_ACTION_NAME
                || spec.action_name == OPENSEARCH_AUTO_PUT_MAPPING_ACTION_NAME
                || spec.action_name == OPENSEARCH_INDICES_ALIASES_ACTION_NAME
                || spec.action_name == OPENSEARCH_UPDATE_SETTINGS_ACTION_NAME
                || spec.action_name == OPENSEARCH_SCALE_INDEX_ACTION_NAME
                || spec.action_name == OPENSEARCH_ANALYZE_ACTION_NAME
                || spec.action_name == OPENSEARCH_CREATE_INDEX_ACTION_NAME
                || spec.action_name == OPENSEARCH_AUTO_CREATE_ACTION_NAME
                || spec.action_name == OPENSEARCH_PUT_STORED_SCRIPT_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_STORED_SCRIPT_ACTION_NAME
                || spec.action_name == OPENSEARCH_DELETE_STORED_SCRIPT_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_SCRIPT_CONTEXT_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_SCRIPT_LANGUAGE_ACTION_NAME
                || spec.action_name == OPENSEARCH_PUT_PIPELINE_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_PIPELINE_ACTION_NAME
                || spec.action_name == OPENSEARCH_DELETE_PIPELINE_ACTION_NAME
                || spec.action_name == OPENSEARCH_SIMULATE_PIPELINE_ACTION_NAME
                || spec.action_name == OPENSEARCH_RESIZE_ACTION_NAME
                || spec.action_name == OPENSEARCH_ROLLOVER_ACTION_NAME
                || spec.action_name == OPENSEARCH_DELETE_INDEX_ACTION_NAME
                || spec.action_name == OPENSEARCH_OPEN_INDEX_ACTION_NAME
                || spec.action_name == OPENSEARCH_CLOSE_INDEX_ACTION_NAME
                || spec.action_name == OPENSEARCH_ADD_INDEX_BLOCK_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_INDEX_ACTION_NAME
                || spec.action_name == OPENSEARCH_INDICES_EXISTS_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_INDEX_TEMPLATES_ACTION_NAME
                || spec.action_name == OPENSEARCH_PUT_INDEX_TEMPLATE_ACTION_NAME
                || spec.action_name == OPENSEARCH_DELETE_INDEX_TEMPLATE_ACTION_NAME
                || spec.action_name == OPENSEARCH_PUT_COMPONENT_TEMPLATE_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_COMPONENT_TEMPLATE_ACTION_NAME
                || spec.action_name == OPENSEARCH_DELETE_COMPONENT_TEMPLATE_ACTION_NAME
                || spec.action_name == OPENSEARCH_PUT_COMPOSABLE_INDEX_TEMPLATE_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_COMPOSABLE_INDEX_TEMPLATE_ACTION_NAME
                || spec.action_name == OPENSEARCH_DELETE_COMPOSABLE_INDEX_TEMPLATE_ACTION_NAME
                || spec.action_name == OPENSEARCH_SIMULATE_INDEX_TEMPLATE_ACTION_NAME
                || spec.action_name == OPENSEARCH_SIMULATE_TEMPLATE_ACTION_NAME
                || spec.action_name == OPENSEARCH_VALIDATE_QUERY_ACTION_NAME
                || spec.action_name == OPENSEARCH_FLUSH_ACTION_NAME
                || spec.action_name == OPENSEARCH_FORCE_MERGE_ACTION_NAME
                || spec.action_name == OPENSEARCH_UPGRADE_ACTION_NAME
                || spec.action_name == OPENSEARCH_UPGRADE_STATUS_ACTION_NAME
                || spec.action_name == OPENSEARCH_UPGRADE_SETTINGS_ACTION_NAME
                || spec.action_name == OPENSEARCH_CLEAR_INDICES_CACHE_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_ALIASES_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_SETTINGS_ACTION_NAME
                || spec.action_name == OPENSEARCH_CLUSTER_SEARCH_SHARDS_ACTION_NAME
                || spec.action_name == OPENSEARCH_FIELD_CAPABILITIES_ACTION_NAME
                || spec.action_name == OPENSEARCH_SEGMENT_REPLICATION_STATS_ACTION_NAME
                || spec.action_name == OPENSEARCH_INDICES_SEGMENTS_ACTION_NAME
                || spec.action_name == OPENSEARCH_PIT_SEGMENTS_ACTION_NAME
                || spec.action_name == OPENSEARCH_INDICES_SHARD_STORES_ACTION_NAME
                || spec.action_name == OPENSEARCH_CREATE_DATA_STREAM_ACTION_NAME
                || spec.action_name == OPENSEARCH_DELETE_DATA_STREAM_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_DATA_STREAM_ACTION_NAME
                || spec.action_name == OPENSEARCH_DATA_STREAMS_STATS_ACTION_NAME
                || spec.action_name == OPENSEARCH_RESOLVE_INDEX_ACTION_NAME
                || spec.action_name == OPENSEARCH_CREATE_VIEW_ACTION_NAME
                || spec.action_name == OPENSEARCH_DELETE_VIEW_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_VIEW_ACTION_NAME
                || spec.action_name == OPENSEARCH_UPDATE_VIEW_ACTION_NAME
                || spec.action_name == OPENSEARCH_LIST_VIEW_NAMES_ACTION_NAME
                || spec.action_name == OPENSEARCH_SEARCH_VIEW_ACTION_NAME
                || spec.action_name == OPENSEARCH_START_PERSISTENT_TASK_ACTION_NAME
                || spec.action_name == OPENSEARCH_UPDATE_PERSISTENT_TASK_STATUS_ACTION_NAME
                || spec.action_name == OPENSEARCH_COMPLETION_PERSISTENT_TASK_ACTION_NAME
                || spec.action_name == OPENSEARCH_REMOVE_PERSISTENT_TASK_ACTION_NAME
                || spec.action_name == OPENSEARCH_ADD_RETENTION_LEASE_ACTION_NAME
                || spec.action_name == OPENSEARCH_RENEW_RETENTION_LEASE_ACTION_NAME
                || spec.action_name == OPENSEARCH_REMOVE_RETENTION_LEASE_ACTION_NAME
                || spec.action_name == OPENSEARCH_LIST_DANGLING_INDICES_ACTION_NAME
                || spec.action_name == OPENSEARCH_IMPORT_DANGLING_INDEX_ACTION_NAME
                || spec.action_name == OPENSEARCH_DELETE_DANGLING_INDEX_ACTION_NAME
                || spec.action_name == OPENSEARCH_FIND_DANGLING_INDEX_ACTION_NAME
                || spec.action_name == OPENSEARCH_SEARCH_ACTION_NAME
                || spec.action_name == OPENSEARCH_STREAM_SEARCH_ACTION_NAME
                || spec.action_name == OPENSEARCH_MULTI_SEARCH_ACTION_NAME
                || spec.action_name == OPENSEARCH_SEARCH_SCROLL_ACTION_NAME
                || spec.action_name == OPENSEARCH_CLEAR_SCROLL_ACTION_NAME
                || spec.action_name == OPENSEARCH_EXPLAIN_ACTION_NAME
                || spec.action_name == OPENSEARCH_CREATE_PIT_ACTION_NAME
                || spec.action_name == OPENSEARCH_DELETE_PIT_ACTION_NAME
                || spec.action_name == OPENSEARCH_GET_ALL_PITS_ACTION_NAME
            {
                assert_eq!(
                    decision.disposition,
                    OpenSearchTransportActionDisposition::Rejected,
                    "{}",
                    spec.action_name
                );
                continue;
            }

            assert_eq!(
                decision.disposition,
                OpenSearchTransportActionDisposition::Missing,
                "{}",
                spec.action_name
            );
            assert!(
                decision
                    .reason
                    .starts_with("priority transport adapter target"),
                "{}",
                spec.action_name
            );
        }

        let unknown = classify_opensearch_transport_action("indices:data/read/unknown");
        assert_eq!(
            unknown.disposition,
            OpenSearchTransportActionDisposition::Missing
        );
        assert_eq!(
            unknown.reason,
            "no OpenSearch transport action adapter is registered"
        );
    }

    #[test]
    fn opensearch_get_request_wire_round_trips_and_maps_to_engine_request() {
        let request = OpenSearchGetRequestWire {
            parent_task_node: "node-a".into(),
            parent_task_id: Some(42),
            ..OpenSearchGetRequestWire::new("logs-000001".into(), "doc-1".into())
        };

        let mut output = StreamOutput::new();
        request.write(&mut output).unwrap();
        let decoded = OpenSearchGetRequestWire::read(output.freeze()).unwrap();

        assert_eq!(decoded, request);
        assert_eq!(
            decoded.to_engine_request().unwrap(),
            GetDocumentRequest {
                index: "logs-000001".into(),
                id: "doc-1".into(),
            }
        );
    }

    #[test]
    fn opensearch_get_request_rejects_unsupported_engine_mapping_options() {
        let request = OpenSearchGetRequestWire {
            routing: Some("tenant-a".into()),
            ..OpenSearchGetRequestWire::new("logs-000001".into(), "doc-1".into())
        };

        match request.to_engine_request().unwrap_err() {
            TransportActionWireError::UnsupportedWireShape { shape, .. } => {
                assert_eq!(shape, "get request routing");
            }
            other => panic!("unexpected error {other:?}"),
        }
    }

    #[test]
    fn opensearch_get_response_wire_round_trips_found_and_missing_documents() {
        let found = OpenSearchGetResponseWire::found(
            "logs-000001".into(),
            DocumentMetadata {
                id: "doc-1".into(),
                version: 3,
                seq_no: 7,
                primary_term: 2,
            },
            json!({ "message": "hello", "tenant": "tenant-a" }),
        );

        let mut output = StreamOutput::new();
        found.write(&mut output).unwrap();
        let decoded = OpenSearchGetResponseWire::read(output.freeze()).unwrap();

        assert_eq!(decoded, found);
        assert_eq!(
            decoded.into_engine_response().unwrap(),
            GetDocumentResponse {
                index: "logs-000001".into(),
                metadata: DocumentMetadata {
                    id: "doc-1".into(),
                    version: 3,
                    seq_no: 7,
                    primary_term: 2,
                },
                source: json!({ "message": "hello", "tenant": "tenant-a" }),
                found: true,
            }
        );

        let missing = OpenSearchGetResponseWire::not_found("logs-000001".into(), "doc-404".into());
        let mut output = StreamOutput::new();
        missing.write(&mut output).unwrap();
        assert_eq!(
            OpenSearchGetResponseWire::read(output.freeze())
                .unwrap()
                .into_engine_response(),
            None
        );
    }

