    fn search_request_body_with_optional_writeable_shape(
        scroll_present: bool,
        source_present: bool,
    ) -> BytesMut {
        let mut output = StreamOutput::new();
        write_parent_task_id(&mut output, "", None);
        output.write_byte(1);
        output.write_string_array(&[]);
        output.write_optional_string(None);
        output.write_optional_string(None);
        output.write_bool(scroll_present);
        if scroll_present {
            return BytesMut::from(&output.freeze()[..]);
        }
        output.write_bool(source_present);
        BytesMut::from(&output.freeze()[..])
    }

    fn explain_request_body_with_concrete_shard_marker() -> BytesMut {
        let mut output = StreamOutput::new();
        write_parent_task_id(&mut output, "", None);
        output.write_bool(true);
        BytesMut::from(&output.freeze()[..])
    }

    #[test]
    fn pending_cluster_tasks_wire_round_trips() {
        let request = PendingClusterTasksRequestWire {
            local: true,
            ..PendingClusterTasksRequestWire::default()
        };
        let mut output = StreamOutput::new();
        request.write(&mut output);
        assert_eq!(
            PendingClusterTasksRequestWire::read(output.freeze()).unwrap(),
            request
        );

        let response = PendingClusterTasksResponseWire {
            tasks: vec![PendingClusterTaskWire {
                insert_order: 1,
                priority: "URGENT".to_string(),
                source: "create-index [logs]".to_string(),
                executing: false,
                time_in_queue_millis: 15,
            }],
        };
        let mut output = StreamOutput::new();
        response.write(&mut output);
        assert_eq!(
            PendingClusterTasksResponseWire::read(output.freeze()).unwrap(),
            response
        );

        let frame =
            build_pending_cluster_tasks_request_message(17, OPENSEARCH_3_7_0_TRANSPORT, &request)
                .unwrap();
        let mut frame = frame;
        let DecodedFrame::Message(message) = decode_frame(&mut frame).unwrap().unwrap() else {
            panic!("expected pending cluster tasks request message");
        };
        assert_eq!(
            read_pending_cluster_tasks_request_message(&message).unwrap(),
            request
        );

        let frame =
            build_pending_cluster_tasks_response_message(17, OPENSEARCH_3_7_0_TRANSPORT, &response)
                .unwrap();
        let mut frame = frame;
        let DecodedFrame::Message(message) = decode_frame(&mut frame).unwrap().unwrap() else {
            panic!("expected pending cluster tasks response message");
        };
        assert_eq!(
            read_pending_cluster_tasks_response_message(&message).unwrap(),
            response
        );
    }

